import random

try:
    import torch
    import torch.nn as nn
except ModuleNotFoundError:
    # Minimal pure-Python stand-in for the few torch pieces used below.
    import math
    import types

    class Size(tuple):
        def __repr__(self):
            return f"torch.Size({list(self)})"

    class Tensor(list):
        @property
        def shape(self):
            return Size((len(self), len(self[0])))

    class Parameter:
        def __init__(self, values):
            self.values = values

        def numel(self):
            return len(self.values)

    class Module:
        def __call__(self, x):
            return self.forward(x)

        def children(self):
            for v in self.__dict__.values():
                if isinstance(v, Module):
                    yield v

        def parameters(self):
            for v in self.__dict__.values():
                if isinstance(v, Parameter):
                    yield v
            for c in self.children():
                yield from c.parameters()

    class Sequential(Module):
        def __init__(self, *layers):
            self.layers = list(layers)

        def children(self):
            return iter(self.layers)

        def forward(self, x):
            for layer in self.layers:
                x = layer(x)
            return x

    class Linear(Module):
        def __init__(self, n_in, n_out, bias=True):
            bound = 1 / math.sqrt(n_in)
            self.w = [[random.uniform(-bound, bound) for _ in range(n_in)] for _ in range(n_out)]
            self.weight = Parameter([v for row in self.w for v in row])
            self.b = [random.uniform(-bound, bound) for _ in range(n_out)] if bias else [0.0] * n_out
            if bias:
                self.bias = Parameter(self.b)

        def forward(self, x):
            return Tensor([[sum(a * b for a, b in zip(row, wr)) + bb
                            for wr, bb in zip(self.w, self.b)] for row in x])

    class BatchNorm1d(Module):
        def __init__(self, n, eps=1e-5):
            self.eps = eps
            self.weight = Parameter([1.0] * n)
            self.bias = Parameter([0.0] * n)

        def forward(self, x):
            n = len(x)
            cols = list(zip(*x))
            means = [sum(c) / n for c in cols]
            vars_ = [sum((v - m) ** 2 for v in c) / n for c, m in zip(cols, means)]
            return Tensor([[(v - m) / math.sqrt(s + self.eps) for v, m, s in zip(row, means, vars_)]
                           for row in x])

    class ReLU(Module):
        def forward(self, x):
            return Tensor([[max(0.0, v) for v in row] for row in x])

    class Dropout(Module):
        def __init__(self, p=0.5):
            self.p = p

        def forward(self, x):
            keep = 1 - self.p
            return Tensor([[v / keep if random.random() < keep else 0.0 for v in row] for row in x])

    nn = types.SimpleNamespace(Module=Module, Sequential=Sequential, Linear=Linear,
                               BatchNorm1d=BatchNorm1d, ReLU=ReLU, Dropout=Dropout)
    torch = types.SimpleNamespace(
        randn=lambda r, c: Tensor([[random.gauss(0, 1) for _ in range(c)] for _ in range(r)]))


class IrisClassifier(nn.Module):
    def __init__(self):
        super().__init__()
        # Bias is redundant before BatchNorm, so the hidden Linear layers omit it.
        self.features = nn.Sequential(
            nn.Linear(4, 32, bias=False),
            nn.BatchNorm1d(32),
            nn.ReLU(),
            nn.Dropout(0.2),
            nn.Linear(32, 16, bias=False),
            nn.BatchNorm1d(16),
            nn.ReLU(),
            nn.Dropout(0.2),
        )
        self.classifier = nn.Linear(16, 3)

    def forward(self, x):
        return self.classifier(self.features(x))


model = IrisClassifier()

# Test with random input
X = torch.randn(10, 4)
output = model(X)
print(f'Output shape: {output.shape}')  # should be [10, 3]
print(f'Total parameters: {sum(p.numel() for p in model.parameters())}')
